{
  "technical_and_design_decisions": [
    "Treat each user story as an independent module migration; modules are not refactored beyond what is needed to fit the s-c-s contract.",
    "Reuse existing Spring XD module code where possible; rewrite only the binding/adaptation layer to match the spring-cloud-stream Source/Sink contracts.",
    "Adopt the spring-cloud-stream convention of a single 'spring-cloud-stream-modules/<module-name>' Maven module per user story.",
    "Keep XD-specific configuration property names where feasible, and add deprecation comments where breaking changes are required.",
    "Tests are adapted from the existing XD module test suites; new end-to-end pipeline tests are added only to verify the source/sink binding.",
    "Shared/common code (e.g., codec helpers for TCP, mail session handling) is factored into a small 'spring-cloud-stream-modules-common' utility module to avoid duplication across the 8 modules."
  ],
  "assumptions": [
    "A single developer performs the entire increment; no parallelization across modules.",
    "Spring XD source is available and the modules are stable, so no bug-fixing of original logic is required beyond API adaptation.",
    "Java 17+ is used (consistent with Spring Framework 6.0 baseline mentioned in the specification).",
    "spring-cloud-stream binder (e.g., Kafka or Rabbit) is provided by the runtime; this work only delivers the application-level modules.",
    "An 8-hour workday is used as the unit of effort.",
    "No production deployment automation, release notes, or backports to earlier Spring versions are in scope.",
    "Module complexity ranking (used to scale per-module effort): simple=2d, medium=3d, complex=4d.",
    "The mongo and mail modules are reused between source and sink stories; the sink/source variants share ~70% of the code, so the second occurrence is lighter."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository and build setup",
      "activity_description": "Create the spring-cloud-stream-modules parent module, configure the Maven build, CI hooks, code style and license headers used across the 8 new modules."
    },
    {
      "activity_id": "A2",
      "activity_name": "Common adapter framework",
      "activity_description": "Implement shared utilities (codec helpers, polling/thread abstractions, common test fixtures) reused by the migrated modules to keep each module's footprint small."
    },
    {
      "activity_id": "A3",
      "activity_name": "Migrate syslog module (source) [U1]",
      "activity_description": "Port the Spring XD syslog source (UDP/TCP listener) to a spring-cloud-stream Source module, including property mapping, unit tests and a basic integration test."
    },
    {
      "activity_id": "A4",
      "activity_name": "Migrate mail module (source) [U2]",
      "activity_description": "Port the Spring XD IMAP/POP3 mail source (polling mailbox) to a spring-cloud-stream Source module with adapted configuration and tests."
    },
    {
      "activity_id": "A5",
      "activity_name": "Migrate tcp module (source) [U3]",
      "activity_description": "Port the Spring XD TCP server source to a spring-cloud-stream Source module, including the reusable codec/decoder layer."
    },
    {
      "activity_id": "A6",
      "activity_name": "Migrate tcp-client module (source) [U4]",
      "activity_description": "Port the Spring XD TCP client source (outbound connection per message) to a spring-cloud-stream Source module, reusing the TCP codec utilities from A5."
    },
    {
      "activity_id": "A7",
      "activity_name": "Migrate gpfdist module (sink) [U5]",
      "activity_description": "Port the Spring XD gpfdist sink (Greenplum external table protocol) to a spring-cloud-stream Sink module. Higher complexity due to the bespoke gpfdist wire protocol."
    },
    {
      "activity_id": "A8",
      "activity_name": "Migrate hdfs-dataset module (sink) [U6]",
      "activity_description": "Port the Spring XD hdfs-dataset sink (file rollover, partitioning, HDFS writer) to a spring-cloud-stream Sink module."
    },
    {
      "activity_id": "A9",
      "activity_name": "Migrate mail module (sink) [U7]",
      "activity_description": "Port the Spring XD SMTP mail sink to a spring-cloud-stream Sink module, sharing most of the mail-session utilities with A4."
    },
    {
      "activity_id": "A10",
      "activity_name": "Migrate mongo module (sink) [U8]",
      "activity_description": "Port the Spring XD MongoDB sink (write to collection) to a spring-cloud-stream Sink module using the Mongo Java driver."
    },
    {
      "activity_id": "A11",
      "activity_name": "End-to-end pipeline integration testing",
      "activity_description": "Build sample spring-cloud-stream pipelines combining the migrated sources and sinks against a local binder to verify they work together as a complete streaming pipeline."
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation and module metadata",
      "activity_description": "Write/update each module's README, configuration property reference and a top-level migration guide documenting how XD users can switch to s-c-s."
    }
  ],
  "activities_with_effort": [
    { "activity_id": "A1",  "most_likely_effort": 2 },
    { "activity_id": "A2",  "most_likely_effort": 3 },
